open_bugs = {"S1": 0, "S2": 2, "S3": 9}
limit     = {"S1": 0, "S2": 1, "S3": 15}
tests = {"pass": 1182, "fail": 6, "blocked": 12, "total": 1200}

for s in limit:
    mark = "OK" if open_bugs[s] <= limit[s] else "기준 초과"
    print(s, open_bugs[s], "/", limit[s], mark)
run = tests["pass"] + tests["fail"]
print(f"실행 {run}/{tests['total']} ({run/tests['total']:.1%}), 통과율 {tests['pass']/run:.1%}")

# S1 0 / 0 OK
# S2 2 / 1 기준 초과
# S3 9 / 15 OK
# 실행 1188/1200 (99.0%), 통과율 99.5%
